section.code:
{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "$id": "https://faion.net/schemas/junior-next-pr-checklist-template.json",
  "title": "Junior next-PR checklist",
  "type": "object",
  "required": ["junior", "mentor", "source_pr", "items", "blocking_item_count", "deferred", "retired", "pairing_sessions", "posting", "review"],
  "additionalProperties": false,
  "properties": {
    "junior": {"type": "string", "minLength": 2},
    "mentor": {"type": "string", "minLength": 2},
    "source_pr": {
      "type": "object",
      "required": ["url", "review_completed_on"],
      "properties": {
        "url": {"type": "string", "pattern": "^https?://"},
        "review_completed_on": {"type": "string", "pattern": "^\\d{4}-\\d{2}-\\d{2}$"}
      }
    },
    "previous_checklist_url": {"type": "string", "pattern": "^https?://"},
    "items": {
      "type": "array",
      "minItems": 3,
      "maxItems": 7,
      "items": {
        "type": "object",
        "required": ["id", "check", "origin_permalink", "severity", "standard", "lint", "status", "ticked_by_junior"],
        "properties": {
          "id": {"type": "string", "pattern": "^c[0-9]+$"},
          "check": {"type": "string", "minLength": 15, "pattern": "^(?!.*\\b(be more|think about|try to|be careful|cleaner code)\\b).*$"},
          "origin_permalink": {"type": "string", "pattern": "^https?://.+#(discussion_r|issuecomment-|r|note_|L)[0-9]+"},
          "severity": {"type": "string", "enum": ["blocking", "should"]},
          "standard": {
            "type": "object",
            "required": ["kind"],
            "properties": {
              "kind": {"type": "string", "enum": ["style_guide", "adr", "contributing", "preference"]},
              "reference": {"type": "string", "minLength": 3},
              "mentor_handle": {"type": "string", "minLength": 2}
            },
            "if": {"properties": {"kind": {"const": "preference"}}},
            "then": {"required": ["mentor_handle"]},
            "else": {"required": ["reference"]}
          },
          "lint": {
            "type": "object",
            "required": ["machine_enforceable"],
            "properties": {
              "machine_enforceable": {"type": "boolean"},
              "rule": {"type": "string", "minLength": 3},
              "automation_ticket": {"type": "string", "minLength": 3},
              "prs_since_automation_landed": {"type": "integer", "minimum": 0, "maximum": 1}
            },
            "if": {"properties": {"machine_enforceable": {"const": true}}},
            "then": {"required": ["rule", "automation_ticket"]}
          },
          "status": {"type": "string", "enum": ["new", "carried", "done"]},
          "carried_count": {"type": "integer", "minimum": 1, "maximum": 2},
          "ticked_by_junior": {"type": "boolean"}
        },
        "allOf": [
          {"if": {"properties": {"status": {"const": "carried"}}}, "then": {"required": ["carried_count"]}},
          {"if": {"properties": {"standard": {"properties": {"kind": {"const": "preference"}}, "required": ["kind"]}}}, "then": {"properties": {"severity": {"const": "should"}}}}
        ]
      }
    },
    "blocking_item_count": {"type": "integer", "minimum": 0, "maximum": 1},
    "deferred": {
      "type": "array",
      "items": {
        "type": "object",
        "required": ["check", "origin_permalink"],
        "properties": {
          "check": {"type": "string", "minLength": 15},
          "origin_permalink": {"type": "string", "pattern": "^https?://.+#(discussion_r|issuecomment-|r|note_|L)[0-9]+"}
        }
      }
    },
    "retired": {
      "type": "array",
      "items": {
        "type": "object",
        "required": ["check", "consecutive_prs_ticked"],
        "properties": {
          "check": {"type": "string", "minLength": 15},
          "consecutive_prs_ticked": {"type": "integer", "minimum": 2}
        }
      }
    },
    "pairing_sessions": {
      "type": "array",
      "items": {
        "type": "object",
        "required": ["check", "carried_count", "scheduled_on"],
        "properties": {
          "check": {"type": "string", "minLength": 15},
          "carried_count": {"type": "integer", "minimum": 3},
          "scheduled_on": {"type": "string", "pattern": "^\\d{4}-\\d{2}-\\d{2}$"}
        }
      }
    },
    "posting": {
      "type": "object",
      "required": ["junior_pastes_into_next_pr_description", "ticks_authored_by", "mentor_verifies_only"],
      "properties": {
        "junior_pastes_into_next_pr_description": {"const": true},
        "ticks_authored_by": {"const": "junior"},
        "mentor_verifies_only": {"const": true}
      }
    },
    "review": {
      "type": "object",
      "required": ["status", "handed_to_junior_by_agent"],
      "properties": {
        "status": {"type": "string", "enum": ["draft", "ready_for_mentor_review", "mentor_confirmed"]},
        "mentor_confirmed_permalinks_and_severity_on": {"type": "string", "pattern": "^\\d{4}-\\d{2}-\\d{2}$"},
        "handed_to_junior_by_agent": {"const": false}
      },
      "if": {"properties": {"status": {"const": "mentor_confirmed"}}},
      "then": {"required": ["mentor_confirmed_permalinks_and_severity_on"]}
    }
  }
}

example.code:
{
  "junior": "@priya",
  "mentor": "@marek",
  "source_pr": {"url": "https://github.com/acme/billing-api/pull/412", "review_completed_on": "2026-06-18"},
  "previous_checklist_url": "https://github.com/acme/billing-api/pull/398#issuecomment-2210001",
  "items": [
    {"id": "c1", "check": "Every new database write in the PR runs inside a transaction or the PR description says why it does not", "origin_permalink": "https://github.com/acme/billing-api/pull/412#discussion_r1893320011", "severity": "blocking", "standard": {"kind": "adr", "reference": "ADR-014 transactional boundaries"}, "lint": {"machine_enforceable": false}, "status": "new", "ticked_by_junior": false},
    {"id": "c2", "check": "The PR description links the ticket and lists the manual test that was run", "origin_permalink": "https://github.com/acme/billing-api/pull/412#issuecomment-2210377", "severity": "should", "standard": {"kind": "contributing", "reference": "CONTRIBUTING.md#pull-request-description"}, "lint": {"machine_enforceable": false}, "status": "carried", "carried_count": 1, "ticked_by_junior": false},
    {"id": "c3", "check": "Every nullable parameter has an explicit guard or a `?` type annotation", "origin_permalink": "https://github.com/acme/billing-api/pull/412#discussion_r1893321440", "severity": "should", "standard": {"kind": "style_guide", "reference": "docs/style-guide.md#nullability"}, "lint": {"machine_enforceable": true, "rule": "mypy --strict-optional", "automation_ticket": "https://github.com/acme/billing-api/issues/419", "prs_since_automation_landed": 0}, "status": "new", "ticked_by_junior": false},
    {"id": "c4", "check": "Every new public function has a docstring stating its return type and raised exceptions", "origin_permalink": "https://github.com/acme/billing-api/pull/412#discussion_r1893322905", "severity": "should", "standard": {"kind": "preference", "mentor_handle": "@marek"}, "lint": {"machine_enforceable": false}, "status": "new", "ticked_by_junior": false}
  ],
  "blocking_item_count": 1,
  "deferred": [
    {"check": "Log lines in the payment path use the structured logger, not print", "origin_permalink": "https://github.com/acme/billing-api/pull/412#discussion_r1893323112"}
  ],
  "retired": [
    {"check": "Every new test file name starts with test_ and lives beside the module it tests", "consecutive_prs_ticked": 2}
  ],
  "pairing_sessions": [],
  "posting": {"junior_pastes_into_next_pr_description": true, "ticks_authored_by": "junior", "mentor_verifies_only": true},
  "review": {"status": "ready_for_mentor_review", "handed_to_junior_by_agent": false}
}

{
  "junior": "@priya",
  "mentor": "@marek",
  "source_pr": {"url": "https://github.com/acme/billing-api/pull/412", "review_completed_on": "2026-06-18"},
  "items": [
    {"id": "c1", "check": "Be more careful with null handling and think about edge cases", "origin_permalink": "https://github.com/acme/billing-api/pull/412#discussion_r1893321440", "severity": "blocking", "standard": {"kind": "preference", "mentor_handle": "@marek"}, "lint": {"machine_enforceable": false}, "status": "carried", "carried_count": 4, "ticked_by_junior": true},
    {"id": "c2", "check": "Imports are sorted and there is no trailing whitespace anywhere in the diff", "origin_permalink": "https://github.com/acme/billing-api/pull/412#discussion_r1893320011", "severity": "blocking", "standard": {"kind": "style_guide", "reference": "docs/style-guide.md#formatting"}, "lint": {"machine_enforceable": true}, "status": "new", "ticked_by_junior": true}
  ],
  "blocking_item_count": 2,
  "deferred": [],
  "retired": [],
  "pairing_sessions": [],
  "posting": {"junior_pastes_into_next_pr_description": false, "ticks_authored_by": "mentor", "mentor_verifies_only": false},
  "review": {"status": "mentor_confirmed", "handed_to_junior_by_agent": true}
}
